import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireVault","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/airevault.md","filePath":"user-guide/airevault.md","lastUpdated":1787059744000}`),a={name:`user-guide/airevault.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="airevault" tabindex="-1">AireVault <a class="header-anchor" href="#airevault" aria-label="Permalink to “AireVault”">​</a></h1><p>Manage the variables and secrets used by your Aire Innovate products from a single, encrypted store.</p><p>The AireVault page is divided into two tabs: <strong>Variables</strong> and <strong>Secrets</strong>.</p><p>Variables and secrets created here can be referenced by:</p><ul class="icon-list"><li><img src="/aireframe-icon.png" width="30" height="30" class="icon-img"> AireFrame</li><li><img src="/aireflow-icon.png" width="30" height="30" class="icon-img"> AireFlow</li><li><img src="/aireassert-icon.png" width="30" height="30" class="icon-img"> AireAssert</li></ul><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><p>Variables store configuration values that are visible in the UI, such as URLs, feature flags, or other non-sensitive settings.</p><p>The table displays:</p><ul><li><strong>Key</strong> – The unique identifier for the variable</li><li><strong>Default Value</strong> – The value used when no scope-specific override applies</li><li><strong>Scopes</strong> – The number of scoped overrides defined, if any</li></ul><p>Click the expand arrow on a row to view all scoped values for that variable.</p><h3 id="creating-and-editing-variables" tabindex="-1">Creating and Editing Variables <a class="header-anchor" href="#creating-and-editing-variables" aria-label="Permalink to “Creating and Editing Variables”">​</a></h3><p>Click <strong>Create</strong> to add a new variable, or use the edit action on an existing row to update its values.</p><p>Each variable has a <strong>key</strong> and one or more <strong>scoped values</strong>:</p><ul><li>Leave the <strong>Scope</strong> field blank to set the <strong>default value</strong>, used whenever no more specific scope matches</li><li>Add named scopes to override the value for specific contexts (for example, a particular environment or client)</li></ul><p>You can add additional scopes with <strong>Add scope</strong>, or remove one with the delete icon. At least one value is required.</p><h3 id="searching-and-sorting" tabindex="-1">Searching and Sorting <a class="header-anchor" href="#searching-and-sorting" aria-label="Permalink to “Searching and Sorting”">​</a></h3><p>Use the search bar to filter variables by key, scope, or value. Click the <strong>Key</strong> column header to toggle sorting alphabetically.</p><h3 id="copying-values" tabindex="-1">Copying Values <a class="header-anchor" href="#copying-values" aria-label="Permalink to “Copying Values”">​</a></h3><p>Use the copy icon on a row to copy the variable&#39;s key, default value, or its full JSON representation to the clipboard.</p><h3 id="importing-and-exporting-variables" tabindex="-1">Importing and Exporting Variables <a class="header-anchor" href="#importing-and-exporting-variables" aria-label="Permalink to “Importing and Exporting Variables”">​</a></h3><p>Use the <strong>More options</strong> (⋯) button in the table toolbar to work with all your variables at once.</p><ul><li><strong>Export All</strong> – Copies all of your variables, including any scoped values, to the clipboard so you can save or share them elsewhere.</li><li><strong>Import</strong> – Opens a window where you can paste in a list of variables to create them all at once, instead of adding each one by hand.</li></ul><p><strong>To export your variables:</strong></p><ol><li>Click <strong>More options</strong> (⋯) above the table.</li><li>Select <strong>Export All</strong>.</li><li>Your variables are copied to the clipboard. Paste them into a file or document to save or share them.</li></ol><p><strong>To import variables:</strong></p><ol><li><p>Click <strong>More options</strong> (⋯) above the table.</p></li><li><p>Select <strong>Import</strong>.</p></li><li><p>In the window that opens, paste in your list of variables. Each variable needs a key and at least one value, for example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;key&quot;: &quot;API_URL&quot;,</span></span>
<span class="line"><span>    &quot;values&quot;: [</span></span>
<span class="line"><span>      { &quot;scope&quot;: &quot;&quot;, &quot;value&quot;: &quot;https://example.com&quot; },</span></span>
<span class="line"><span>      { &quot;scope&quot;: &quot;Staging&quot;, &quot;value&quot;: &quot;https://staging.example.com&quot; }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>]</span></span></code></pre></div></li><li><p>Any variables in your list that already exist will be highlighted, so you can see what will be affected. By default, these are left as they are. If you&#39;d rather replace them with the values you&#39;re importing, turn on <strong>Overwrite existing variables</strong> and confirm — since changing a variable can affect anything that already uses it, such as an AireFlow task.</p></li><li><p>Click <strong>Import</strong> to finish.</p></li></ol><p>These options only appear if you have permission to view or add variables.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to “Secrets”">​</a></h2><p>Secrets store sensitive values, such as API keys or credentials. Secret values are never displayed in the table and are masked by default when entering or editing them.</p><p>The table displays:</p><ul><li><strong>Key</strong> – The unique identifier for the secret</li><li><strong>Scopes</strong> – The number of scoped overrides defined, if any</li></ul><h3 id="creating-and-editing-secrets" tabindex="-1">Creating and Editing Secrets <a class="header-anchor" href="#creating-and-editing-secrets" aria-label="Permalink to “Creating and Editing Secrets”">​</a></h3><p>Click <strong>Create</strong> to add a new secret, or use the edit action on an existing row to update its values. Secrets use the same scoped value model as variables:</p><ul><li>Leave the <strong>Scope</strong> field blank to set the <strong>default value</strong></li><li>Add named scopes to override the value for specific contexts</li></ul><p>Secret values are hidden by default. Use the visibility icon to reveal a value while editing, or the file import button to load it from a file.</p><h3 id="searching-and-sorting-1" tabindex="-1">Searching and Sorting <a class="header-anchor" href="#searching-and-sorting-1" aria-label="Permalink to “Searching and Sorting”">​</a></h3><p>Use the search bar to filter secrets by key. Click the <strong>Key</strong> column header to toggle sorting alphabetically.</p><h3 id="copying-keys" tabindex="-1">Copying Keys <a class="header-anchor" href="#copying-keys" aria-label="Permalink to “Copying Keys”">​</a></h3><p>Use the copy icon on a row to copy the secret&#39;s key to the clipboard.</p><h3 id="importing-and-exporting-secrets" tabindex="-1">Importing and Exporting Secrets <a class="header-anchor" href="#importing-and-exporting-secrets" aria-label="Permalink to “Importing and Exporting Secrets”">​</a></h3><p>Use the <strong>More options</strong> (⋯) button in the table toolbar to work with all your secrets at once.</p><ul><li><strong>Export All</strong> – Copies your secrets to the clipboard, including their keys, scopes, and any related details. Actual secret values are never included in the export — they&#39;re replaced with a placeholder to keep them safe.</li><li><strong>Import</strong> – Opens a window where you can paste in a list of secrets, including their values, to create them all at once.</li></ul><p><strong>To export your secrets:</strong></p><ol><li>Click <strong>More options</strong> (⋯) above the table.</li><li>Select <strong>Export All</strong>.</li><li>Your secrets are copied to the clipboard, with keys, scopes, and any related details – but not the actual values, which are replaced with a placeholder.</li></ol><p><strong>To import secrets:</strong></p><ol><li><p>Click <strong>More options</strong> (⋯) above the table.</p></li><li><p>Select <strong>Import</strong>.</p></li><li><p>In the window that opens, paste in your list of secrets, including their values, for example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;key&quot;: &quot;API_KEY&quot;,</span></span>
<span class="line"><span>    &quot;values&quot;: [</span></span>
<span class="line"><span>      { &quot;scope&quot;: &quot;&quot;, &quot;value&quot;: &quot;actual-secret-value&quot; },</span></span>
<span class="line"><span>      { &quot;scope&quot;: &quot;Staging&quot;, &quot;value&quot;: &quot;another-secret-value&quot; }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>]</span></span></code></pre></div></li><li><p>As with variables, any secrets in your list that already exist will be highlighted. By default, these are left as they are. If you&#39;d rather replace them, turn on <strong>Overwrite existing secrets</strong> and confirm.</p></li><li><p>Click <strong>Import</strong> to finish.</p></li></ol><p>You&#39;ll need permission to view secrets to use Export, and permission to add secrets to use Import.</p><h2 id="deleting-variables-and-secrets" tabindex="-1">Deleting Variables and Secrets <a class="header-anchor" href="#deleting-variables-and-secrets" aria-label="Permalink to “Deleting Variables and Secrets”">​</a></h2><p>Use the delete icon on a row to remove a variable or secret. You&#39;ll be asked to confirm, as this permanently deletes all of its scoped values and cannot be undone.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><p>Access to Variables and Secrets is controlled separately by permission. If you do not have permission to view a tab, you&#39;ll see an <strong>Access Denied</strong> message instead of the table. Create, edit, delete actions are only shown if you hold the relevant permission.</p>`,51)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};